-- Fiches de vente des 7 produits : accroche, histoire, bénéfices, mode d'emploi, conseil,
-- questions fréquentes, produits associés. Seules les promesses imprimées sur les étiquettes
-- sont reprises (aucun avis, aucune durée de tenue inventée).
alter table public.produits
  add column if not exists fiche jsonb not null default '{}'::jsonb
    check (jsonb_typeof(fiche) = 'object');

comment on column public.produits.fiche is
  'Fiche de vente : {accroche, histoire, benefices[], utilisation[], conseil, faq[{q,r}], associes[slug]}';

update public.produits set fiche = $fiche${"accroche": "La pose qui tient, sans y penser.", "histoire": "Une belle pose se joue sur la ligne frontale. Lace Glue sèche vite et tient fort : vous fixez la dentelle, vous la plaquez, et vous vivez votre journée sans vérifier votre lace à chaque miroir.", "benefices": ["Séchage rapide : la pose avance, vous n'attendez pas", "Tenue ultra forte, du matin au soir", "Embout fin pour déposer des couches régulières le long du front", "Pour les professionnelles comme pour la pose à la maison"], "utilisation": ["Nettoyez la peau du front (sans crème ni huile) et laissez sécher.", "Déposez une fine couche le long de la ligne frontale et attendez qu'elle devienne transparente.", "Pour plus de tenue, ajoutez une deuxième couche fine, toujours jusqu'à transparence.", "Posez la dentelle et pressez de l'avant vers l'arrière, du bout des doigts ou au peigne à queue.", "Finissez avec Lace Melting Spray et un bandeau élastique pour une lisière invisible."], "conseil": "Plusieurs couches fines tiennent mieux qu'une couche épaisse : c'est le secret d'une pose propre et sans surplus.", "faq": [{"q": "Combien de temps tient la pose ?", "r": "Cela dépend de votre peau, de la chaleur et de l'entretien. Pour la meilleure tenue : peau bien nettoyée, couches fines et pas d'eau sur la ligne frontale pendant les premières heures."}, {"q": "Comment la retirer sans abîmer la dentelle ?", "r": "Avec Lace Glue Remover Spray : vaporisez sur les bords, laissez agir, puis décollez doucement. Ne tirez jamais à sec."}, {"q": "J'ai la peau sensible, je peux l'utiliser ?", "r": "Faites d'abord un essai sur une petite zone, derrière l'oreille, 24 heures avant votre première pose."}], "associes": ["lace-melting-spray", "lace-glue-remover-spray"]}$fiche$::jsonb where slug = 'lace-glue';
update public.produits set fiche = $fiche${"accroche": "La dentelle disparaît. Il ne reste que vous.", "histoire": "Ce qui trahit une perruque, c'est la ligne de la dentelle. Lace Melting Spray la fond dans la peau : la lisière devient invisible, naturelle de près comme en photo. Il sèche vite, tient fort et convient aussi à la pose sans colle.", "benefices": ["Effet « fondu » : la dentelle se confond avec la peau", "Séchage rapide", "Tenue ultra forte", "Compatible avec la pose sans colle (glueless)"], "utilisation": ["Posez et ajustez votre perruque.", "Vaporisez sur la dentelle, le long de la ligne frontale, à une quinzaine de centimètres.", "Placez un bandeau élastique sur la lisière.", "Laissez sécher complètement sous le bandeau, puis retirez-le."], "conseil": "Associé à Lace Glue en dessous, vous cumulez la tenue de la colle et l'invisibilité du spray.", "faq": [{"q": "Faut-il de la colle avec ?", "r": "Non, il convient à la pose sans colle. Pour une tenue renforcée, utilisez-le par-dessus Lace Glue."}, {"q": "Comment obtenir une finition nette ?", "r": "Vaporisez à distance, en couche légère, et laissez bien sécher sous le bandeau avant de toucher la lisière."}], "associes": ["lace-glue", "lace-glue-remover-spray"]}$fiche$::jsonb where slug = 'lace-melting-spray';
update public.produits set fiche = $fiche${"accroche": "Retirer sa perruque, en douceur.", "histoire": "Le retrait compte autant que la pose : c'est là que la dentelle s'abîme et que les cheveux du front souffrent. Lace Glue Remover Spray agit vite sur la colle : la perruque se décolle sans forcer et la dentelle reste prête pour la prochaine pose.", "benefices": ["Action rapide sur la colle", "La perruque se décolle sans tirer", "Préserve la dentelle pour vos prochaines poses", "Format de poche, à glisser dans le sac"], "utilisation": ["Vaporisez généreusement sur les bords de la dentelle.", "Laissez agir quelques instants.", "Soulevez doucement la dentelle de l'arrière vers l'avant ; revaporisez si ça résiste.", "Nettoyez le front, puis lavez la dentelle avec Glue Residue Remover Shampoo."], "conseil": "Si ça résiste, n'insistez pas : revaporisez et attendez. La patience protège vos cheveux du front.", "faq": [{"q": "Est-ce que ça abîme la dentelle ?", "r": "Le spray dissout la colle au lieu de l'arracher : c'est la façon la plus douce de retirer une perruque et de garder sa dentelle intacte."}, {"q": "Il marche sur toutes les colles ?", "r": "Il est formulé pour les colles de pose de perruque, dont Lace Glue. Pour une colle très ancienne, laissez agir un peu plus longtemps."}], "associes": ["glue-residue-remover-shampoo", "lace-glue"]}$fiche$::jsonb where slug = 'lace-glue-remover-spray';
update public.produits set fiche = $fiche${"accroche": "Repartir sur une base propre.", "histoire": "Après le retrait, il reste toujours des traces de colle : dans les cheveux, sur la peau, dans la dentelle. Ce shampoing est fait pour elles. Il nettoie en profondeur pour que votre prochaine pose tienne sur une base nette.", "benefices": ["Élimine les résidus de colle", "Sur vos cheveux comme sur la dentelle de la perruque", "Prépare une base propre pour la pose suivante", "Dernière étape du rituel Glorious Destiny"], "utilisation": ["Mouillez les cheveux ou la dentelle.", "Appliquez et massez doucement en insistant sur les zones de colle.", "Laissez poser quelques instants, puis rincez abondamment.", "Renouvelez si des résidus persistent."], "conseil": "Pour la dentelle : lavez-la à plat, sans frotter, puis laissez-la sécher à l'air libre.", "faq": [{"q": "Je peux l'utiliser sur mes propres cheveux ?", "r": "Oui : il est fait pour enlever la colle aussi bien des cheveux que de la dentelle."}, {"q": "Pourquoi pas un shampoing classique ?", "r": "Un shampoing classique n'est pas conçu pour les résidus de colle : ils restent dans la dentelle et fragilisent la pose suivante."}], "associes": ["lace-glue-remover-spray", "lace-glue"]}$fiche$::jsonb where slug = 'glue-residue-remover-shampoo';
update public.produits set fiche = $fiche${"accroche": "Des boucles définies, souples et brillantes.", "histoire": "Vos boucles méritent mieux qu'un effet carton. Hair Curl Mousse définit chaque boucle, tient longtemps et ne laisse aucun résidu blanc. Les cheveux restent brillants et hydratés, au toucher comme à l'œil.", "benefices": ["Définit tous les types de boucles", "Tenue longue durée", "Aucun résidu blanc", "Brillance et hydratation"], "utilisation": ["Sur cheveux propres et humides, agitez le flacon.", "Prenez une noix de mousse dans la main.", "Répartissez mèche par mèche en froissant des pointes vers les racines.", "Laissez sécher à l'air libre ou au diffuseur, sans toucher."], "conseil": "Moins vous touchez pendant le séchage, plus la boucle est nette. Ne froissez qu'une fois les cheveux secs.", "faq": [{"q": "Ça marche sur une perruque bouclée ?", "r": "Oui, sur une perruque en cheveux naturels comme sur vos cheveux, pour raviver la définition des boucles."}, {"q": "Mes cheveux vont-ils être rêches ?", "r": "Non : la mousse apporte brillance et hydratation, sans résidu blanc ni effet cartonné."}], "associes": ["wax-stick", "braid-gel"]}$fiche$::jsonb where slug = 'hair-curl-mousse';
update public.produits set fiche = $fiche${"accroche": "Des tresses nettes, du premier au dernier rang.", "histoire": "Cornrows, locks ou twists : le rendu se joue sur la netteté des raies et des contours. Braid Gel offre une tenue extrême pour des tresses propres qui restent en place, sans mèches qui s'échappent.", "benefices": ["Tenue extrême", "Pour cornrows, locks et twists", "Raies et contours nets", "Grand pot de 250 g, pratique en salon"], "utilisation": ["Démêlez et séparez la section à tresser.", "Prélevez une petite quantité au doigt ou au peigne.", "Lissez la section, du cuir chevelu vers les pointes.", "Tressez aussitôt pour un résultat net."], "conseil": "Pour des raies parfaites, déposez le gel au peigne fin directement sur la ligne de séparation.", "faq": [{"q": "Pour les locks, au départ ou à l'entretien ?", "r": "Les deux : il discipline les repousses et garde les locks en place."}, {"q": "Il convient aux cheveux courts ?", "r": "Oui : une petite quantité suffit pour lisser les contours et les raies."}], "associes": ["wax-stick", "hair-curl-mousse"]}$fiche$::jsonb where slug = 'braid-gel';
update public.produits set fiche = $fiche${"accroche": "Le geste net, partout, tout le temps.", "histoire": "Un cheveu du front qui rebique, une mèche qui s'échappe d'un chignon, un contour de tresse à reprendre : Wax Stick se glisse dans le sac et règle tout en un geste. Sa tenue extrême lisse et discipline sans effort.", "benefices": ["Tenue extrême", "Stick nomade : pas de doigts gras", "Contours, tresses, locks et twists", "Retouches rapides dans la journée"], "utilisation": ["Retirez le capuchon.", "Passez le stick directement sur la mèche ou le contour.", "Lissez à la brosse pour un fini net."], "conseil": "Nouez un foulard en satin quelques minutes après l'application : le fini est plus lisse et tient plus longtemps.", "faq": [{"q": "Pour les cheveux courts ?", "r": "Oui : il discipline les mèches rebelles et les contours, quelle que soit la longueur."}, {"q": "Quelle différence avec Braid Gel ?", "r": "Braid Gel se travaille sur toute la section pendant le tressage ; Wax Stick sert aux finitions et aux retouches, n'importe où."}], "associes": ["braid-gel", "hair-curl-mousse"]}$fiche$::jsonb where slug = 'wax-stick';
